interface Ponto {
  x: number;
  y: number;
}

type Coordenada = { x: number; y: number };

const p: Ponto = { x: 1, y: 2 };

// nomes diferentes, mesma forma: a atribuição funciona nos dois sentidos
const c: Coordenada = p;
const devolta: Ponto = c;

console.log(c.x, devolta.y); // 1 2

function distanciaOrigem(ponto: Ponto): number {
  return Math.hypot(ponto.x, ponto.y);
}

console.log(distanciaOrigem(c)); // 2.23606797749979

interface Etiqueta {
  nome: string;
}

// @ts-expect-error forma diferente: um Ponto não tem a propriedade nome
const e: Etiqueta = p;
console.log(e); // { x: 1, y: 2 }

interface Utilizador {
  id: number;
  nome: string;
}

function saudar(u: Utilizador): string {
  return `Ola, ${u.nome}`;
}

const admin = {
  id: 1,
  nome: "Ana",
  permissoes: ["tudo"],
  ultimoLogin: "2024-05-01",
};

// admin tem duas propriedades a mais, mas cumpre o contrato Utilizador
console.log(saudar(admin)); // "Ola, Ana"

const guardado: Utilizador = admin;
console.log(guardado.id, guardado.nome); // 1 "Ana"

// @ts-expect-error o valor em memória tem permissoes, mas o tipo Utilizador não
console.log(guardado.permissoes);

console.log(admin.permissoes); // ["tudo"]

interface Config {
  largura: number;
  altura: number;
}

// @ts-expect-error literal de objeto fresco: altrua é uma propriedade desconhecida
const comGralha: Config = { largura: 100, altura: 50, altrua: 10 };
console.log(comGralha.largura); // 100

// o MESMO objeto, passando primeiro por uma variável, já é aceite
const solto = { largura: 100, altura: 50, extra: true };
const aceite: Config = solto;
console.log(aceite.altura); // 50

function aplicar(config: Config): number {
  return config.largura * config.altura;
}

// @ts-expect-error o excess property check também atua no argumento literal
aplicar({ largura: 4, altura: 5, cor: "azul" });

console.log(aplicar(solto)); // 5000

interface Opcoes {
  titulo: string;
  visivel: boolean;
  tema?: string;
}

// 1. variável intermédia: o objeto deixa de ser fresco e o check não corre
const bruto = { titulo: "Painel", visivel: true, debug: true };
const porVariavel: Opcoes = bruto;

// 2. assertion com as: cala o check, mas também cala as gralhas
const porAssertion = { titulo: "Painel", visivel: true, tena: "escuro" } as Opcoes;

// 3. index signature: o próprio tipo passa a declarar que admite extras
interface OpcoesAbertas {
  titulo: string;
  visivel: boolean;
  [chave: string]: unknown;
}
const porIndexSignature: OpcoesAbertas = {
  titulo: "Painel",
  visivel: true,
  debug: true,
};

console.log(porVariavel.titulo); // "Painel"
console.log(porAssertion.tema); // undefined
console.log(porIndexSignature["debug"]); // true

type IdUtilizador = string;
type IdProduto = string;

function carregarUtilizador(id: IdUtilizador): string {
  return `utilizador ${id}`;
}

const idProduto: IdProduto = "prod-42";

// nenhum erro: para o compilador ambos os tipos são apenas string
console.log(carregarUtilizador(idProduto)); // "utilizador prod-42"

interface Metros {
  valor: number;
}
interface Pes {
  valor: number;
}

const altura: Metros = { valor: 10 };
const comprimento: Pes = altura; // mesma forma, nenhum aviso

console.log(comprimento.valor); // 10

type IdUtilizador = string & { readonly __marca: "utilizador" };
type IdProduto = string & { readonly __marca: "produto" };

function criarIdUtilizador(valor: string): IdUtilizador {
  return valor as IdUtilizador;
}

function criarIdProduto(valor: string): IdProduto {
  return valor as IdProduto;
}

function carregarUtilizador(id: IdUtilizador): string {
  return `utilizador ${id}`;
}

const idU = criarIdUtilizador("u-1");
const idP = criarIdProduto("p-9");

console.log(carregarUtilizador(idU)); // "utilizador u-1"

// @ts-expect-error IdProduto deixou de ser intercambiável com IdUtilizador
carregarUtilizador(idP);

// @ts-expect-error uma string solta não passa sem a função criadora
carregarUtilizador("u-2");

// em execução continua a ser apenas uma string
console.log(idU.toUpperCase()); // "U-1"

interface Encomenda {
  id: string;
  total: number;
  cliente: { nome: string; email: string };
}

// o erro fala de email e da forma do objeto, nunca do nome Encomenda
const incompleta: Encomenda = {
  id: "e-1",
  total: 10,
  // @ts-expect-error Property 'email' is missing in type '{ nome: string; }'
  cliente: { nome: "Ana" },
};

console.log(incompleta.id); // "e-1"

// o lado bom da mesma moeda: um duplo de teste serve sem declarar nada
interface Relogio {
  agora(): number;
}

const relogioFalso = { agora: () => 0, chamadas: 0 };

function medir(relogio: Relogio): number {
  return relogio.agora();
}

console.log(medir(relogioFalso)); // 0

