interface Livro {
  titulo: string;
  paginas: number;
}

type Publicacao = { titulo: string; paginas: number };

function descrever(item: Livro): string {
  return `${item.titulo} (${item.paginas} p.)`;
}

const revista: Publicacao = { titulo: "TS Mensal", paginas: 40 };
console.log(descrever(revista)); // "TS Mensal (40 p.)"

const manual = { titulo: "Manual", paginas: 120, editora: "Casa" };
console.log(descrever(manual)); // "Manual (120 p.)"

// @ts-expect-error literal de objeto direto: editora é uma propriedade desconhecida
descrever({ titulo: "Guia", paginas: 10, editora: "Casa" });

interface Pedido {
  produto: string;
  quantidade: number;
}

function linha(pedido: Pedido): string {
  return `${pedido.quantidade} x ${pedido.produto}`;
}

// @ts-expect-error gralha apanhada: quantidde não existe e quantidade falta
const comGralha: Pedido = { produto: "Caneta", quantidde: 3 };
console.log(comGralha.produto); // "Caneta"

// contorno 1: variável intermédia, para dados que trazem campos a mais
const bruto = { produto: "Caderno", quantidade: 2, origem: "csv" };
const pedidoA: Pedido = bruto;

// contorno 2: assertion, quando a intenção é mesmo ignorar o extra
const pedidoB = { produto: "Lapis", quantidade: 5, origem: "api" } as Pedido;

console.log(linha(pedidoA)); // "2 x Caderno"
console.log(linha(pedidoB)); // "5 x Lapis"

interface Evento {
  nome: string;
  timestamp: number;
  [extra: string]: string | number | boolean | undefined;
}

function resumir(evento: Evento): string {
  return `${evento.nome} @ ${evento.timestamp}`;
}

const clique: Evento = {
  nome: "clique",
  timestamp: 1700000000,
  botao: "esquerdo",
  duplo: false,
};

console.log(resumir(clique)); // "clique @ 1700000000"
console.log(clique["botao"]); // "esquerdo"

// @ts-expect-error a index signature continua a limitar o TIPO dos valores extra
const invalido: Evento = { nome: "scroll", timestamp: 1, alvo: { id: 2 } };
console.log(invalido.nome); // "scroll"

// @ts-expect-error a index signature não dispensa as propriedades obrigatórias
const semNome: Evento = { timestamp: 2 };
console.log(semNome.timestamp); // 2

type IdUtilizador = string & { readonly __marca: "utilizador" };
type IdEncomenda = string & { readonly __marca: "encomenda" };

function criarIdUtilizador(valor: string): IdUtilizador {
  if (!valor.startsWith("u-")) {
    throw new Error(`id de utilizador inválido: ${valor}`);
  }
  return valor as IdUtilizador;
}

function criarIdEncomenda(valor: string): IdEncomenda {
  if (!valor.startsWith("e-")) {
    throw new Error(`id de encomenda inválido: ${valor}`);
  }
  return valor as IdEncomenda;
}

function encomendasDe(id: IdUtilizador): string {
  return `encomendas de ${id}`;
}

const idU = criarIdUtilizador("u-7");
const idE = criarIdEncomenda("e-3");

console.log(encomendasDe(idU)); // "encomendas de u-7"
console.log(idE.toUpperCase()); // "E-3"

// @ts-expect-error IdEncomenda não é atribuível a IdUtilizador
encomendasDe(idE);

// @ts-expect-error uma string comum não passa sem a função criadora
encomendasDe("u-8");
